const normalize = (value: string) => value.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-z0-9]+/g, ' ').trim();
const machineNames = new Set(machineExercises.map((exercise) => normalize(exercise.en)));
const muscleOrder: Muscle[] = ['Peito', 'Costas', 'Pernas', 'Ombros', 'Braços', 'Abdômen'];

export const exercises: Exercise[] = [
  ...baseExercises.filter((exercise) => !machineNames.has(normalize(exercise.en))),
  ...machineExercises
].sort((a, b) => muscleOrder.indexOf(a.muscle) - muscleOrder.indexOf(b.muscle) || a.name.localeCompare(b.name, 'pt-BR'));
